/// <summary>
/// Keeps gameplay / Invector camera FOV on the optics zoom target.
/// Invector's vThirdPersonCamera overwrites fieldOfView every FixedUpdate from state.fov.
/// </summary>
public void ApplyOpticsCameraFov(bool immediate = false)
{
    if (!_opticsOpen || !_opticsDriveFov)
        return;

    if (immediate)
        _opticsCurrentFov = _opticsTargetFov;
    else
    {
        _opticsCurrentFov = Mathf.Lerp(
            _opticsCurrentFov,
            _opticsTargetFov,
            Time.deltaTime * Mathf.Max(opticsZoomLerpSpeed, 0.01f));
