using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Pull third-person camera to near first-person. Invector's useZoom path clamps to
/// minDistance (~1.5 via EnsurePioneerZoomState), so we disable useZoom and drive defaultDistance.
/// </summary>
public void ApplyOpticsCameraDistance()
{
    if (!_opticsOpen || !_opticsPushCameraForward)
        return;

    float distance = Mathf.Max(0f, binocularCameraDistance);
    var tpCamera = ResolveInvectorTpCamera();
    if (tpCamera != null)
    {
        // useZoom=false → CameraMovement assigns currentZoom = defaultDistance (bypasses 1.5m min).
        if (tpCamera.currentState != null)
        {
            tpCamera.currentState.useZoom = false;
            tpCamera.currentState.defaultDistance = distance;
        }

        if (tpCamera.lerpState != null)
        {
            tpCamera.lerpState.useZoom = false;
            tpCamera.lerpState.defaultDistance = distance;
        }

        tpCamera.distance = distance;
        return;
    }

    _currentFollowDistance = distance;
    followDistance = distance;
}

private void CaptureAndPushOpticsCameraDistance()
{
    var tpCamera = ResolveInvectorTpCamera();
    if (tpCamera != null)
    {
        _opticsSavedCameraDistance = tpCamera.distance > 0.01f
            ? tpCamera.distance
            : (tpCamera.currentState != null ? tpCamera.currentState.defaultDistance : followDistance);

        if (tpCamera.currentState != null)
        {
            _opticsSavedStateDefaultDistance = tpCamera.currentState.defaultDistance;
            _opticsSavedStateMinDistance = tpCamera.currentState.minDistance;
            _opticsSavedStateMaxDistance = tpCamera.currentState.maxDistance;
            _opticsSavedUseZoom = tpCamera.currentState.useZoom;
        }
    }
    else
    {
        _opticsSavedCameraDistance = _currentFollowDistance > 0.01f ? _currentFollowDistance : followDistance;
    }

    ApplyOpticsCameraDistance();
    SetPlayerMeshVisibleForBinoculars(false);
}

private void RestoreOpticsCameraDistance()
{
    SetPlayerMeshVisibleForBinoculars(true);

    var tpCamera = ResolveInvectorTpCamera();
    if (tpCamera != null && _opticsSavedCameraDistance > 0.01f)
    {
        tpCamera.distance = _opticsSavedCameraDistance;
        if (tpCamera.currentState != null)
        {
            tpCamera.currentState.useZoom = _opticsSavedUseZoom;
            if (_opticsSavedStateDefaultDistance > 0.01f)
                tpCamera.currentState.defaultDistance = _opticsSavedStateDefaultDistance;
            if (_opticsSavedStateMinDistance > 0.01f)
                tpCamera.currentState.minDistance = _opticsSavedStateMinDistance;
            if (_opticsSavedStateMaxDistance > 0.01f)
                tpCamera.currentState.maxDistance = _opticsSavedStateMaxDistance;
        }

        if (tpCamera.lerpState != null)
        {
            tpCamera.lerpState.useZoom = _opticsSavedUseZoom;
            if (_opticsSavedStateDefaultDistance > 0.01f)
                tpCamera.lerpState.defaultDistance = _opticsSavedStateDefaultDistance;
        }
    }
    else if (_opticsSavedCameraDistance > 0.01f)
    {
        followDistance = _opticsSavedCameraDistance;
        _currentFollowDistance = _opticsSavedCameraDistance;
    }

    _opticsSavedCameraDistance = -1f;
    _opticsSavedStateDefaultDistance = -1f;
    _opticsSavedStateMinDistance = -1f;
    _opticsSavedStateMaxDistance = -1f;
    _opticsSavedUseZoom = true;
}

private void SetPlayerMeshVisibleForBinoculars(bool visible)
{
    if (!hidePlayerMeshInBinoculars)
        return;

    if (visible)
    {
        for (int i = 0; i < _opticsHiddenRenderers.Count; i++)
        {
            Renderer renderer = _opticsHiddenRenderers[i];
            if (renderer != null)
                renderer.enabled = true;
        }

        _opticsHiddenRenderers.Clear();
        return;
    }

    _opticsHiddenRenderers.Clear();
    Renderer[] renderers = GetComponentsInChildren<Renderer>(true);
    for (int i = 0; i < renderers.Length; i++)
    {
        Renderer renderer = renderers[i];
        if (renderer == null || !renderer.enabled)
            continue;
        if (renderer is ParticleSystemRenderer || renderer is TrailRenderer || renderer is LineRenderer)
            continue;

        renderer.enabled = false;
        _opticsHiddenRenderers.Add(renderer);
    }
}

