/// <summary>
/// Keep binocular mask + crosshair circular across aspect ratios.
/// Scene setup used non-uniform scales (e.g. 1.5×1.35 root, 6.25×7 mask) which ovalize on widescreen.
/// </summary>
private void FitBinocularOverlayToCircle()
{
    RectTransform root = binocularRoot != null ? binocularRoot.transform as RectTransform : null;
    if (root == null)
        return;

    RectTransform parent = root.parent as RectTransform;
    if (parent == null)
        return;

    float parentW = parent.rect.width;
    float parentH = parent.rect.height;
    if (parentW < 1f || parentH < 1f)
        return;

    float side = Mathf.Min(parentW, parentH);
    root.anchorMin = new Vector2(0.5f, 0.5f);
    root.anchorMax = new Vector2(0.5f, 0.5f);
    root.pivot = new Vector2(0.5f, 0.5f);
    root.anchoredPosition = Vector2.zero;
    root.sizeDelta = new Vector2(side, side);
    root.localScale = Vector3.one;
    root.localEulerAngles = Vector3.zero;

    for (int i = 0; i < root.childCount; i++)
    {
        RectTransform child = root.GetChild(i) as RectTransform;
        if (child == null)
            continue;

        // Uniform scale only — preserve relative size via the larger authored axis.
        Vector3 authored = child.localScale;
        float uniform = Mathf.Max(Mathf.Abs(authored.x), Mathf.Abs(authored.y), 0.01f);
        // Mask / rings authored with huge scales were compensating for stretch; clamp to fill square.
        if (uniform > 1.01f)
            uniform = 1f;

        child.localScale = new Vector3(uniform, uniform, 1f);
        child.anchorMin = Vector2.zero;
        child.anchorMax = Vector2.one;
        child.pivot = new Vector2(0.5f, 0.5f);
        child.offsetMin = Vector2.zero;
        child.offsetMax = Vector2.zero;
        child.anchoredPosition = Vector2.zero;
        child.sizeDelta = Vector2.zero;

        Image image = child.GetComponent<Image>();
        if (image != null)
        {
            image.preserveAspect = true;
            image.type = Image.Type.Simple;
        }
    }
}

