private static float GetInvectorCurrentZoom(vThirdPersonCamera tpCamera)
{
    if (tpCamera == null)
        return -1f;

    PropertyInfo prop = ResolveInvectorCurrentZoomProperty();
    if (prop == null)
        return tpCamera.distance;

    object value = prop.GetValue(tpCamera);
    return value is float zoom ? zoom : tpCamera.distance;
}

private static void SetInvectorCurrentZoom(vThirdPersonCamera tpCamera, float zoom)
{
    if (tpCamera == null)
        return;

    PropertyInfo prop = ResolveInvectorCurrentZoomProperty();
    if (prop != null && prop.CanWrite)
        prop.SetValue(tpCamera, zoom);
}

private static PropertyInfo ResolveInvectorCurrentZoomProperty()
{
    if (invectorCurrentZoomProperty != null)
        return invectorCurrentZoomProperty;

    invectorCurrentZoomProperty = typeof(vThirdPersonCamera).GetProperty(
        "currentZoom",
        BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
    return invectorCurrentZoomProperty;
}

