/// <summary>
/// Keep binocular mask + crosshair circular across aspect ratios.
/// Crosshair layers draw first; Mask Image is forced last so reticle stays inside the hole.
/// </summary>
private void FitBinocularOverlayToCircle()
{
    RectTransform root = binocularRoot != null ? binocularRoot.transform as RectTransform : null;
    if (root == null)
        return;

    RectTransform parent = root.parent as RectTransform;
    if (parent == null)
        return;

    float parentW = parent.rect.width;
    float parentH = parent.rect.height;
    if (parentW < 1f || parentH < 1f)
        return;

    // Full-screen black plate (letterbox outside the circular hole).
    root.anchorMin = Vector2.zero;
    root.anchorMax = Vector2.one;
    root.pivot = new Vector2(0.5f, 0.5f);
    root.offsetMin = Vector2.zero;
    root.offsetMax = Vector2.zero;
    root.anchoredPosition = Vector2.zero;
    root.sizeDelta = Vector2.zero;
    root.localScale = Vector3.one;
    root.localEulerAngles = Vector3.zero;

    Image rootImage = binocularRoot.GetComponent<Image>();
    if (rootImage != null)
    {
        rootImage.color = Color.black;
        rootImage.enabled = true;
        rootImage.raycastTarget = false;
    }

    RectTransform maskRect = null;
    for (int i = 0; i < root.childCount; i++)
    {
        RectTransform child = root.GetChild(i) as RectTransform;
        if (child == null)
            continue;

        if (child.name.IndexOf("mask", System.StringComparison.OrdinalIgnoreCase) >= 0)
            maskRect = child;

        // Stretch to parent; AspectRatioFitter locks a centered 1:1 square (true circle on any aspect).
        child.localScale = Vector3.one;
        child.localEulerAngles = Vector3.zero;
        child.anchorMin = Vector2.zero;
        child.anchorMax = Vector2.one;
        child.pivot = new Vector2(0.5f, 0.5f);
        child.offsetMin = Vector2.zero;
        child.offsetMax = Vector2.zero;
        child.anchoredPosition = Vector2.zero;
        child.sizeDelta = Vector2.zero;

        AspectRatioFitter fitter = child.GetComponent<AspectRatioFitter>();
        if (fitter == null)
            fitter = child.gameObject.AddComponent<AspectRatioFitter>();
        fitter.aspectMode = AspectRatioFitter.AspectMode.FitInParent;
        fitter.aspectRatio = 1f;

        Image image = child.GetComponent<Image>();
        if (image != null)
        {
            image.preserveAspect = true;
            image.type = Image.Type.Simple;
        }
    }

    // Mask must render above crosshair / scope art so reticle is only visible through the hole.
    if (maskRect != null)
        maskRect.SetAsLastSibling();

    Canvas.ForceUpdateCanvases();
    LayoutRebuilder.ForceRebuildLayoutImmediate(root);
}

