public override void CameraInput()
{
    if (!cameraMain || tpCamera == null || !CanReadCameraInput())
        return;

    EnsureRuntimeZoomState();

    float x = 0f;
    float y = 0f;
    if (!lockCameraInput && Mouse.current != null)
    {
        Vector2 delta = Mouse.current.delta.ReadValue();
        x = delta.x * MouseLookScale;
        y = delta.y * MouseLookScale;
    }

    if (invertCameraInputHorizontal)
        x *= -1f;

    if (invertCameraInputVertical)
        y *= -1f;

    tpCamera.RotateCamera(x, y);

    if (!lockCameraInput && Mouse.current != null)
    {
        // Binocular FOV zoom is owned by OpticsController — don't also change follow distance.
        bool opticsOwnsScroll = _playerController != null && _playerController.IsOpticsOpen;
        if (!opticsOwnsScroll)
        {
            float scroll = Mouse.current.scroll.ReadValue().y / ScrollUnitsPerNotch * scrollZoomNotchScale;
            if (Mathf.Abs(scroll) > 0.001f)
                tpCamera.Zoom(scroll);
        }
    }
}

private void EnsureRuntimeZoomState()
{
    if (tpCamera?.currentState == null)
        return;

    // Always enforce playable third-person zoom range. Prior optics code could leave
    // distance/currentZoom near zero; never treat that as the player's intended zoom.
    float liveDistance = tpCamera.distance > 0.01f ? tpCamera.distance : 0f;
    float stateDefault = tpCamera.currentState.defaultDistance;
    float currentDistance = liveDistance >= runtimeMinCameraDistance
        ? liveDistance
        : (stateDefault >= runtimeMinCameraDistance
            ? stateDefault
            : runtimeDefaultCameraDistance);

    tpCamera.currentState.useZoom = true;
    tpCamera.currentState.minDistance = runtimeMinCameraDistance;
    tpCamera.currentState.maxDistance = Mathf.Max(runtimeMaxCameraDistance, currentDistance);
    tpCamera.currentState.defaultDistance = Mathf.Clamp(
        stateDefault >= runtimeMinCameraDistance ? stateDefault : runtimeDefaultCameraDistance,
        runtimeMinCameraDistance,
        tpCamera.currentState.maxDistance);

    if (tpCamera.lerpState != null)
    {
        tpCamera.lerpState.useZoom = true;
        tpCamera.lerpState.minDistance = tpCamera.currentState.minDistance;
        tpCamera.lerpState.maxDistance = tpCamera.currentState.maxDistance;
        tpCamera.lerpState.defaultDistance = tpCamera.currentState.defaultDistance;
    }

    // Pull an illegally-close camera back to a playable third-person distance.
    if (tpCamera.distance < runtimeMinCameraDistance - 0.01f)
        tpCamera.ForceSetZoomDistance(tpCamera.currentState.defaultDistance);
}

