public static void ApplyPlayerShotRecoil(vShooterManager shooterManager, ItemData weaponItem, ItemData ammoItem = null)
{
    if (shooterManager == null)
        return;

    vThirdPersonCamera camera = shooterManager.tpCamera;
    if (camera == null || !camera.isInit)
        return;

    ResolveRecoilKick(weaponItem, ammoItem, out float verticalKick, out float horizontalKick);
    if (Mathf.Abs(verticalKick) < 0.001f && Mathf.Abs(horizontalKick) < 0.001f)
        return;

    // Ammo profile values are degrees — apply directly to tpCamera pitch/yaw.
    // Do not route through RotateCamera + mouse-pixel scale (that made recoil invisible).
    camera.mouseY -= verticalKick;
    camera.mouseX += horizontalKick;

    if (camera.currentState != null)
    {
        camera.mouseY = vExtensions.ClampAngle(
            camera.mouseY,
            camera.currentState.yMinLimit,
            camera.currentState.yMaxLimit);
        camera.mouseX = vExtensions.ClampAngle(
            camera.mouseX,
            camera.currentState.xMinLimit,
            camera.currentState.xMaxLimit);
    }

    camera.CheckCameraIsRotating();
}

